import type {
  BorrowerProfile,
  Lender,
  MortgageProductType,
  MortgageRate,
} from "@/types/mortgage";
import { FIXED_TERMS, VARIABLE_TERMS } from "@/types/mortgage";

/**
 * ⚠️ DEMONSTRATION MORTGAGE RATES — NOT LENDER QUOTES ⚠️
 *
 * The institutions below are real. The rates are not: they are generated by this
 * file, they were never published by any of these lenders, and nothing here was
 * scraped from a bank website. They exist so the comparison tool has something
 * coherent to compare before a real rate source is connected.
 *
 * Do not use these numbers to choose a lender. Every one of them is a placeholder
 * for a figure only the lender can give you.
 *
 * ── Replacing these with real rates ─────────────────────────────────────
 * Nothing outside `data/demo/` imports this file. The application talks to a
 * `MortgageRateRepository` (lib/data/mortgage-repository.ts); point that at a
 * database and this generator simply stops being read. See
 * docs/MORTGAGE_RATE_PIPELINE.md.
 */

export const DEMO_RATE_SOURCE_ID = "src-demo-mortgage-rates";

/** Held fixed so the generated rates are stable across renders and restarts. */
export const DEMO_RATE_EFFECTIVE_DATE = "2026-06-15";
