/**
 * Base rates the generator varies around, by product, term and borrower profile.
 *
 * Insured rows sit below uninsured ones on purpose. An insured mortgage carries a
 * default-insurance premium, which makes it *safer* for the lender, so it is
 * normally quoted at a lower rate. Getting that direction right matters: it is
 * why a 5%-down scenario can show a lower rate and still cost far more overall.
 */
const BASE_RATES: Record<
  MortgageProductType,
  Record<BorrowerProfile, Record<number, number>>
> = {
  fixed: {
    uninsured: { 1: 5.84, 2: 5.34, 3: 4.99, 5: 4.79, 7: 5.19, 10: 5.59 },
    insured: { 1: 5.59, 2: 5.09, 3: 4.74, 5: 4.54, 7: 4.99, 10: 5.39 },
  },
  variable: {
    uninsured: { 3: 5.45, 5: 5.35 },
    insured: { 3: 5.2, 5: 5.1 },
  },
};

/** Small, fast, seedable PRNG — the same one the market generator uses. */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function hashString(value: string): number {
  let hash = 2166136261;
  for (let i = 0; i < value.length; i += 1) {
    hash ^= value.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

/**
 * Each lender gets a stable offset from the base, so the ordering of the
 * comparison is consistent between renders rather than reshuffling on every
 * request. The spread is roughly ±20 basis points, which is the order of
 * magnitude posted rates actually differ by.
 */
function lenderOffset(lenderId: string, productType: MortgageProductType): number {
  const random = mulberry32(hashString(`${lenderId}:${productType}:offset`));
  return Math.round((random() * 0.38 - 0.16) * 100) / 100;
}

/** Rates are quoted to two decimals and land on a 0.01 boundary. */
function roundRate(value: number): number {
  return Math.round(value * 100) / 100;
}

function buildRate(
  lender: Lender,
  productType: MortgageProductType,
  termYears: number,
  borrowerProfile: BorrowerProfile,
): MortgageRate {
  const base = BASE_RATES[productType][borrowerProfile][termYears];
  const random = mulberry32(
    hashString(`${lender.id}:${productType}:${termYears}:${borrowerProfile}`),
  );
  // Per-term jitter on top of the lender's overall stance, so a lender that is
  // sharp on five-year fixed is not automatically sharp on everything.
  const jitter = Math.round((random() * 0.12 - 0.06) * 100) / 100;

  return {
    id: `demo-${lender.id}-${productType}-${termYears}-${borrowerProfile}`,
    lenderId: lender.id,
    productType,
    termYears,
    borrowerProfile,
    rate: roundRate(Math.max(0.5, base + lenderOffset(lender.id, productType) + jitter)),
    effectiveDate: DEMO_RATE_EFFECTIVE_DATE,
    dataSourceId: DEMO_RATE_SOURCE_ID,
    dataQuality: "demo",
    lastUpdated: DEMO_RATE_LAST_UPDATED,
  };
}

/** Every generated rate row: lender × product × term × borrower profile. */
export function generateDemoRates(): MortgageRate[] {
  const rates: MortgageRate[] = [];
  const profiles: BorrowerProfile[] = ["insured", "uninsured"];

  for (const lender of LENDERS) {
    for (const profile of profiles) {
      for (const term of FIXED_TERMS) {
        rates.push(buildRate(lender, "fixed", term, profile));
      }
      for (const term of VARIABLE_TERMS) {
        rates.push(buildRate(lender, "variable", term, profile));
      }
    }
  }

  return rates;
}

let cachedRates: MortgageRate[] | null = null;

/** Generated once per process, like the market dataset. */
export function getDemoRates(): MortgageRate[] {
  if (!cachedRates) cachedRates = generateDemoRates();
  return cachedRates;
}
